'use strict';

// MODULES //

var tape = require( 'tape' );
var hasProp = require( '@stdlib/assert/has-property' );
var isFunction = require( '@stdlib/assert/is-function' );
var Float64Array = require( './../lib' );


// TESTS //

tape( 'main export is a function', function test( t ) {
	t.ok( true, __filename );
	t.strictEqual( typeof Float64Array, 'function', 'main export is a function' );
	t.end();
});

tape( 'a typed array instance has a `reduce` method', function test( t ) {
	var arr = new Float64Array( 2 );
	t.strictEqual( hasProp( arr, 'reduce' ), true, 'has property' );
	t.strictEqual( isFunction( arr.reduce ), true, 'has method' );
	t.end();
});

tape( 'the method throws an error if invoked with a `this` context which is not a typed array instance', function test( t ) {
	var values;
	var arr;
	var i;

	arr = new Float64Array( 5 );

	values = [
		'5',
		5,
		NaN,
		true,
		false,
		null,
		void 0,
		{},
		[],
		function noop() {}
	];
	for ( i = 0; i < values.length; i++ ) {
		t.throws( badValue( values[i] ), TypeError, 'throws an error when provided '+values[i] );
	}
	t.end();

	function badValue( value ) {
		return function badValue() {
			return arr.reduce.call( value, add );
		};
	}

	function add( acc, v ) {
		return acc + v;
	}
});

tape( 'the method throws an error if provided a first argument which is not a function', function test( t ) {
	var values;
	var arr;
	var i;

	arr = new Float64Array( 10 );

	values = [
		'5',
		3.14,
		NaN,
		true,
		false,
		null,
		void 0,
		{},
		[]
	];
	for ( i = 0; i < values.length; i++ ) {
		t.throws( badValue( values[i] ), TypeError, 'throws an error when provided '+values[i] );
	}
	t.end();

	function badValue( value ) {
		return function badValue() {
			return arr.reduce( value );
		};
	}
});

tape( 'the method throws an error if not provided an initial value when operating on an empty typed array', function test( t ) {
	var arr;

	arr = new Float64Array( 0 );
	t.throws( foo, TypeError, 'throws an error' );
	t.end();

	function foo() {
		arr.reduce( add );
	}

	function add( acc, v ) {
		return acc + v;
	}
});

tape( 'the method uses the first element as the initial value when no initial value is provided', function test( t ) {
	var actual;
	var arr;

	arr = new Float64Array( [ 1.0, 2.0, 3.0 ] );
	actual = arr.reduce( add );

	t.strictEqual( actual, 6.0, 'returns expected value' );
	t.end();

	function add( acc, v ) {
		return acc + v;
	}
});

tape( 'the method supports providing an initial value as the second argument', function test( t ) {
	var actual;
	var arr;

	arr = new Float64Array( [ 1.0, 2.0, 3.0 ] );
	actual = arr.reduce( add, 10.0 );

	t.strictEqual( actual, 16.0, 'returns expected value' );
	t.end();

	function add( acc, v ) {
		return acc + v;
	}
});

tape( 'the method returns the accumulated result', function test( t ) {
	var actual;
	var arr;

	arr = new Float64Array( [ 1.0, 2.0, 3.0, 4.0 ] );
	actual = arr.reduce( add );

	t.strictEqual( actual, 10.0, 'returns expected value' );
	t.end();

	function add( acc, v ) {
		return acc + v;
	}
});

tape( 'the callback receives the accumulator, current value, and index as arguments', function test( t ) {
	var indices;
	var values;
	var arr;

	arr = new Float64Array( [ 1.0, 2.0, 3.0 ] );
	indices = [];
	values = [];

	arr.reduce( function reducer( acc, v, i ) {
		values.push( v );
		indices.push( i );
		return acc + v;
	}, 0.0 );

	t.deepEqual( values, [ 1.0, 2.0, 3.0 ], 'returns expected value' );
	t.deepEqual( indices, [ 0, 1, 2 ], 'returns expected value' );
	t.end();
});
